CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE doc_chunks (
    id        BIGSERIAL PRIMARY KEY,
    source    TEXT,
    content   TEXT,
    embedding VECTOR(384)
);

CREATE INDEX ON doc_chunks USING hnsw (embedding vector_cosine_ops);

-- 5 most similar chunks to the query vector (<=> is cosine distance)
SELECT content, source
FROM doc_chunks
ORDER BY embedding <=> '[0.12, -0.03, ...]'::vector
LIMIT 5;

import json
from anthropic import Anthropic

client = Anthropic()

def get_order_status(order_id: str) -> dict:
    return {"order_id": order_id, "status": "shipped", "eta": "2 days"}   # real DB call here

TOOLS = {"get_order_status": get_order_status}
tools = [{
    "name": "get_order_status",
    "description": "Get the delivery status of a customer's order by order ID.",
    "input_schema": {
        "type": "object",
        "properties": {"order_id": {"type": "string", "description": "Order ID like A123"}},
        "required": ["order_id"],
    },
}]

messages = [{"role": "user", "content": "Where is my order A123?"}]
while True:
    response = client.messages.create(model="claude-opus-5-5", max_tokens=4096,
                                      tools=tools, messages=messages)
    messages.append({"role": "assistant", "content": response.content})
    if response.stop_reason != "tool_use":
        break
    results = []
    for block in response.content:
        if block.type == "tool_use":
            output = TOOLS[block.name](**block.input)
            results.append({"type": "tool_result", "tool_use_id": block.id,
                            "content": json.dumps(output)})
    messages.append({"role": "user", "content": results})   # all results in one message

print(next(b.text for b in response.content if b.type == "text"))
